import React, { useState, useEffect } from 'react';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';
import './AttendancePage.css';
import axios from 'axios';
import moment from 'moment';

const createMockTimeLogs = (employees) => { /* ... (same as before) ... */ };

const AttendancePage = () => {
  const [allEmployees, setAllEmployees] = useState([]);
  const [allTimeLogs, setAllTimeLogs] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  // --- NEW STATE FOR FILTERS ---
  const [departmentFilter, setDepartmentFilter] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');

  const [selectedDate, setSelectedDate] = useState(new Date());

  useEffect(() => {
    const fetchAndPrepareData = async () => {
      setIsLoading(true);
      try {
        const response = await axios.get('http://127.0.0.1:8000/api/employees/');
        const employeesData = response.data.results || response.data || [];
        setAllEmployees(employeesData);
        if (employeesData.length > 0) {
            setAllTimeLogs(createMockTimeLogs(employeesData));
        }
      } catch (error) {
        console.error("Failed to fetch employees:", error);
      } finally {
        setIsLoading(false);
      }
    };
    fetchAndPrepareData();
  }, []);

  // --- NEW, ADVANCED FILTERING LOGIC ---
  const employeesToDisplay = allEmployees
    // First, filter by department
    .filter(emp => departmentFilter === 'All' || emp.department === departmentFilter)
    // Then, filter by the search query on name
    .filter(emp => 
      `${emp.firstName} ${emp.lastName}`.toLowerCase().includes(searchQuery.toLowerCase())
    );

  // Get a unique list of departments for the filter dropdown
  const departments = [...new Set(allEmployees.map(emp => emp.department))];

  // Filter the logs for the daily table based on the final employee list and selected date
  const dailyLogs = allTimeLogs.filter(log => 
    moment(log.date).isSame(selectedDate, 'day') &&
    employeesToDisplay.some(emp => emp.id === log.employee.id) // Check if the log's employee is in our filtered display list
  );

  const tileClassName = ({ date, view }) => { /* ... (same as before) ... */ };

  return (
    <div className="p-8">
      {/* === UPDATED HEADER WITH NEW FILTERS === */}
      <div className="flex flex-col md:flex-row justify-between md:items-center gap-4 mb-6">
        <div>
          <h1 className="text-3xl font-bold">Attendance Calendar</h1>
          <p className="text-sm text-subtext-light">Filter by department or search for a specific employee.</p>
        </div>
        <div className="flex items-center gap-4 w-full md:w-auto">
          {/* Department Filter */}
          <select 
            value={departmentFilter}
            onChange={(e) => setDepartmentFilter(e.target.value)}
            className="w-full md:w-48"
          >
            <option value="All">All Departments</option>
            {departments.map(dept => <option key={dept} value={dept}>{dept}</option>)}
          </select>

          {/* Search Bar */}
          <div className="relative w-full md:w-64">
            <span className="material-icons absolute left-3 top-1/2 -translate-y-1/2 text-subtext-light">search</span>
            <input 
              type="text"
              placeholder="Search by name..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10"
            />
          </div>
        </div>
      </div>

      <div className="bg-card-light dark:bg-card-dark p-4 rounded-xl shadow-sm">
        <Calendar
          onChange={setSelectedDate}
          value={selectedDate}
          tileClassName={tileClassName}
          className="w-full border-none"
        />
      </div>

      <div className="mt-8">
        <h3 className="text-xl font-semibold mb-4">
          Logs for {moment(selectedDate).format('MMMM Do, YYYY')}
        </h3>
        {/* The table will now automatically update based on the filters */}

      </div>
    </div>
  );
};


export default AttendancePage;
